const items = $input.all();
const threshold = 100 * 1024 * 1024; // 100MB in bytes

const largeFiles = items.filter(item => {
  const size = Number(item.json.size || 0);
  return size > threshold;
}).map(item => {
  const sizeMB = Math.round(Number(item.json.size) / (1024 * 1024) * 100) / 100;
  return {
    json: {
      name: item.json.name,
      id: item.json.id,
      sizeMB,
      mimeType: item.json.mimeType,
      owner: item.json.owners?.[0]?.emailAddress || 'Unknown',
      lastModified: item.json.modifiedTime,
      link: item.json.webViewLink || ''
    }
  };
});

return largeFiles.length > 0 ? largeFiles : [{ json: { noLargeFiles: true, message: 'No files over 100MB found' } }];
